    vowels = "aeiouAEIOU"
    n = len(word)

    for i in range(1, n-1):
        if word[i] in vowels:
            left_is_consonant = not (word[i-1].lower() in 'aeiou')
            right_is_consonant = not (word[i+1].lower() in 'aeiou')

